{"query":"
  query GetDealersByCountry ($country: String!, $limit: Int, $offset: Int) {
    GetDealersByCountry (country: $country, limit: $limit, offset: $offset) {
      vicinityId
      name
      region
      country
      city
      addressLines
      zipCode
      telephoneNumbers
      email
      websites
      logoImageUrl
      latitude
      longitude
      serviceIds
      salesforceDealer
      pickUpCollect
      dealerFranchises{
        franchiseCode
      }
      shopOpeningHours {
        openingHoursClosed
        openingHoursDay
        openingHoursOpen
        openingHoursType
    }
      openingHours {
        TR {
          serviceWeek
          serviceWeekend
          shopWeek
          shopWeekend
        }
      }
    }
  }
","variables":{"country":"tr"}}

{"query":"
  query GetCategoriesByCountry ($country: String!, $limit: Int, $offset: Int) {
    GetCategoriesByCountry (country: $country, limit: $limit, offset: $offset) {
      categories {
        categoryId
        categoryName
        franchises {
          franchiseCode
          franchiseDescription
        }
        services {
            serviceId
            serviceName
        }
      },
      language
    }
  }
","variables":{"country":"tr"}}
